contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: actor (the caller) and amount to send.
    // General rule: after a successful call to addToBalance by actor sending amount,
    // c.getBalance(actor) == previous_balance + amount.
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero to avoid silly zero-address semantics
        vm.assume(actor != address(0));
        // bound amount to a wide range but within available account funding limits
        amount = bound(amount, 0, 2**200);

        // fund the actor so they can send the amount
        vm.deal(actor, amount);

        // record previous balance as reported by contract
        uint256 before = c.getBalance(actor);

        // perform the call as the actor sending `amount` wei
        vm.prank(actor);
        // call and capture whether it succeeded (should succeed on reference for all amounts that don't overflow in storage semantics)
        bool ok;
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted, then the reference implementation would revert only on true arithmetic overflow
        // (Solidity ^0.8.0). However the intended general property we assert is only about successful calls:
        // when the call succeeds, the stored balance must equal before + amount.
        if (ok) {
            uint256 after = c.getBalance(actor);
            assertTrue(after == before + amount);
        } else {
            // If the call reverted, still assert the stored balance was unchanged (reentrant safety):
            // But to keep a single general assertion that holds for all inputs on reference and is violated by mutant,
            // we assert that either the call succeeded and balance updated by amount, or the call reverted and balance unchanged.
            // Represent this as a single boolean condition to assertTrue on the contract-observed values.
            uint256 after = c.getBalance(actor);
            assertTrue((ok && after == before + amount) || (!ok && after == before));
        }
    }
}

