contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule we assert: For any EOA origin 'originEOA', any contract forwarder 'forwarder', and any amount > 0,
    // when the EOA sends 'amount' to the forwarder and the forwarder forwards that exact amount to c.addToBalance(),
    // the correct contract C will always increase userBalance[forwarder] by exactly 'amount' (i.e., getBalance(forwarder) == amount),
    // because the require in the correct contract checks userBalance[msg.sender] (the forwarder). The mutant that checks
    // userBalance[tx.origin] may instead gate based on the EOA's balance and thus can reject or accept differently causing
    // userBalance[forwarder] to differ. We fuzz originEOA, amount, and use a deployed Forwarder helper contract to model
    // a contract caller (so tx.origin != msg.sender).
    function testFuzz_property(address originEOA, uint256 amount) public {
        // Keep domain wide but sensible: originEOA must be nonzero EOA and not the contract c nor this test contract
        vm.assume(originEOA != address(0));
        vm.assume(originEOA != address(this));
        vm.assume(originEOA != address(c));

        // bound amount to avoid overflow gas extremes; allow zero to be tested too
        amount = bound(amount, 0, 1 ether);

        // Deploy a minimal forwarder contract which will receive funds from originEOA and forward them to c
        Forwarder f = new Forwarder(address(c));

        // Fund the originEOA so it can send to forwarder
        vm.deal(originEOA, amount);

        // The originEOA calls the forwarder to forward 'amount' to c.addToBalance()
        vm.prank(originEOA);
        // call forwarder.depositAndForward{value: amount}()
        f.depositAndForward{value: amount}();

        // Now assert the universal property: the correct contract must have credited the forwarder with exactly 'amount'
        // We read via the public getter getBalance(forwarder)
        assertTrue(c.getBalance(address(f)) == amount);
    }
}

