contract Forwarder {
    address target;
    constructor(address _target) { target = _target; }
    // payable function that forwards all received ETH to C.addToBalance()
    function depositAndForward() external payable {
        // forward all value to target.addToBalance()
        (bool s, ) = target.call{value: msg.value}(abi.encodeWithSignature("addToBalance()"));
        require(s, "forward failed");
    }
    receive() external payable {}
}

