contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single test function that is parameterized by two addresses and an amount
    // addrOwner: the address whose balance will be funded and then queried
    // caller: the address that will call getBalance (simulated by this contract; we cannot change msg.sender for calls, so we use two addresses only for clarity)
    // amount: Ether to add to addrOwner's balance
    function check(address payable addrOwner, address caller, uint256 amount) public payable {
        // Preconditions: this contract must hold sufficient ETH to fund the deposit
        require(address(this).balance >= amount, "insufficient balance for test");
        // Make sure addresses are non-zero
        require(addrOwner != address(0) && caller != address(0), "zero address");

        // Step 1: fund addrOwner's balance by calling addToBalance from this contract
        // We must call as the owner whose balance will increase; since we cannot impersonate arbitrary addresses,
        // we use addrOwner by transferring Ether to the contract c via this contract's call only when msg.sender is this contract.
        // To ensure we update the mapping for addrOwner, first we require addrOwner == address(this) OR bail.
        // The distinguishing property relies on querying arbitrary address u; to make the property general and reachable,
        // we require addrOwner to be this contract so addToBalance affects userBalance[this].
        require(addrOwner == address(this), "addrOwner must be this contract for actionable state change");

        // perform the deposit to c from this contract
        c.addToBalance{value: amount}();

        // Observe balance via getBalance queried for addrOwner
        uint bal_for_owner = c.getBalance(addrOwner);
        // Observe balance via getBalance queried with this contract as caller (same in P; differs in M when u != msg.sender)
        uint bal_for_caller = c.getBalance(address(this));

